INSERT INTO `ebooks` VALUES (1,'Laravel: Up & Running','laravel-up-running','A complete guide to the Laravel PHP framework. Learn to build modern web applications with Laravel from the ground up. Covers routing, Eloquent ORM, Blade templating, queues, and more.','Matt Stauffer',80000.00,NULL,'ebooks/LRxiXFYVXPSdlXwMrteeAxF0qPQiMWkws1BDc6qn.pdf','Teknologi','published','2026-05-16 13:57:08','2026-05-20 14:58:28'),(2,'Clean Code','clean-code','Clean Code adalah panduan praktis untuk menulis kode yang bersih dan mudah dipelihara.','Robert C. Martin',120000.00,'https://images-na.ssl-images-amazon.com/images/I/41SH-SvWPxL.jpg','ebooks/vAOrje3itFHBdeI5jBwF48qLXl82dcaX74Ffa45m.pdf','Teknologi','published','2026-05-16 13:57:08','2026-05-20 14:53:38'),(3,'The Pragmatic Programmer','the-pragmatic-programmer','Your Journey to Mastery. This book will help you become a better programmer. Topics range from personal responsibility to career development, and include architectural techniques to keep code flexible.','David Thomas & Andrew Hunt',110000.00,NULL,'ebooks/rWDS4vZ743Wwt8yH8aao60ue5frpxQa6UxODVAlv.pdf','Teknologi','published','2026-05-16 13:57:08','2026-05-20 14:55:42'),(4,'JavaScript: The Good Parts','javascript-the-good-parts','Most programming languages contain good and bad parts, but JavaScript has more than its share of the bad. This book identifies the goodness in JavaScript that makes it work well.','Douglas Crockford',99000.00,NULL,'ebooks/GSo4eMMlfnxTEnisK0dFxKXC4NU75Vn8Sury0HBE.pdf','Teknologi','published','2026-05-16 13:57:08','2026-05-20 14:56:32'),(5,'Python Crash Course','python-crash-course','Pengantar Python praktis dengan proyek nyata.','Eric Matthes',115000.00,'https://covers.openlibrary.org/b/isbn/9781593279288-L.jpg','ebooks/fy0nfkZbhR5BUY11RBIkNMikEX4qG9maMOd2urZq.pdf','Teknologi','published','2026-05-16 13:57:08','2026-05-20 15:37:10'),(6,'Design Patterns','design-patterns','Pola desain klasik untuk software berorientasi objek.','Erich Gamma et al.',135000.00,'https://covers.openlibrary.org/b/isbn/9780201633610-L.jpg','ebooks/OcUW6r7r00AmU0ItP0TBMiD2xH0LlHEiPhUtl2ef.pdf','Teknologi','published','2026-05-16 13:57:08','2026-05-20 14:59:40'),(7,'CSS: The Definitive Guide','css-the-definitive-guide','If you\'re a web designer or app developer interested in sophisticated page styling, improved accessibility, and saving time and effort, this comprehensive guide is essential reading.','Eric A. Meyer',90000.00,NULL,'ebooks/gQMXsteGXOAK4ZAK4WgZI8QG3nicFQvFLkmYe5Md.pdf','Teknologi','published','2026-05-16 13:57:08','2026-05-20 15:10:02'),(8,'Domain-Driven Design','domain-driven-design','Tackling Complexity in the Heart of Software. This is not a book about specific technologies. It\'s about how you think about the problems you\'re solving.','Eric Evans',145000.00,NULL,'ebooks/uiGPjk4BDwU9XdcdLiBAnJKyCGZloQClZhNQ4sT4.pdf','Teknologi','draft','2026-05-16 13:57:08','2026-05-20 15:04:01'),(9,'Laut Bercerita','laut-bercerita','Laut Bercerita adalah novel yang mengisahkan perjuangan, kehilangan, dan harapan di masa penuh gejolak.','Leila S. Chudori',79000.00,'laut-bercerita.jpeg','ebooks/SvPsFVaf5IzLFXGQohCKZNBZxVdHJDT9sxCOLY4P.pdf','Novel','published','2026-05-16 14:53:55','2026-05-20 14:23:56'),(10,'Atomic Habits','atomic-habits','Atomic Habits menjelaskan bagaimana perubahan kecil yang konsisten dapat membentuk hasil besar.','James Clear',0.00,'https://images-na.ssl-images-amazon.com/images/I/91bYsX41DVL.jpg','ebooks/TTlKikyTS7LEJWwFEvcJzjHKA8weMsiFbUOQg8qd.pdf','Pengembangan Diri','published','2026-05-16 14:53:55','2026-05-20 14:27:14'),(11,'Sapiens','sapiens','Sapiens membahas evolusi manusia dari masa purba hingga modern.','Yuval Noah Harari',135000.00,'https://images-na.ssl-images-amazon.com/images/I/713jIoMO3UL.jpg','ebooks/KvQKPux60nOrPkJmy8AXD5oi6VhPmvVm9Kab3TnL.pdf','Sejarah','published','2026-05-16 14:53:55','2026-05-20 14:31:55'),(12,'Psychology of Money','psychology-of-money','Psychology of Money mengeksplorasi bagaimana orang berpikir tentang uang.','Morgan Housel',0.00,'https://images-na.ssl-images-amazon.com/images/I/71g2ednj0JL.jpg','ebooks/s1vgGowWQCPxvTZK4CyyU30eR8oWzbmCnseC8ZHW.pdf','Bisnis','published','2026-05-16 14:53:55','2026-05-20 14:34:57'),(13,'Mindset','mindset','Mindset menjelaskan perbedaan antara fixed mindset dan growth mindset.','Carol S. Dweck',0.00,'mindset.jpeg','ebooks/0l4PLP1jIJlmNXHLccMFszYCSq4gGQcDQJBM38gl.pdf','Pengembangan Diri','published','2026-05-16 14:53:55','2026-05-20 14:29:53'),(14,'Dune','dune','Kisah epik di gurun Arrakis tentang kekuasaan, takdir, dan perebutan rempah.','Frank Herbert',118000.00,'https://images-na.ssl-images-amazon.com/images/I/91uwocAMtSL.jpg','ebooks/bj3J1tPPXrTG9eavoNmmWn3zprLqfqVZPJp1oCaV.pdf','Fiksi','published','2026-05-16 14:53:55','2026-05-20 14:30:45'),(15,'The Alchemist','the-alchemist','Novel reflektif tentang keberanian mengikuti mimpi dan menemukan tujuan pribadi.','Paulo Coelho',84000.00,'https://images-na.ssl-images-amazon.com/images/I/71aFt4+OTOL.jpg','ebooks/x9DUIIPxG2Z5CJ8ACaexFpGt4xjizA2KB2HgWkWX.pdf','Fiksi','published','2026-05-16 14:53:55','2026-05-20 14:33:22'),(16,'The Midnight Library','the-midnight-library','Kisah emosional tentang kemungkinan hidup yang berbeda, penyesalan, dan harapan.','Matt Haig',92000.00,'https://images-na.ssl-images-amazon.com/images/I/81J6APjwxlL.jpg','ebooks/YXkKp8XgNLUdhXQOr3eVDAVXs1p81olWhlQJ6XVF.pdf','Fiksi','published','2026-05-16 14:53:55','2026-05-20 14:34:26'),(17,'Ikigai','ikigai','Rahasia hidup panjang dan bahagia dari Jepang melalui tujuan dan kebiasaan kecil.','Hector Garcia',88000.00,'https://images-na.ssl-images-amazon.com/images/I/81l3rZK4lnL.jpg','ebooks/Z6rH9XAPfNnBPSFPET6Qz7SKuQBY14ihlhQXpGBW.pdf','Pengembangan Diri','published','2026-05-16 14:53:55','2026-05-20 14:35:34'),(18,'Norwegian Wood','norwegian-wood','Novel tentang memori, kehilangan, dan masa muda.','Haruki Murakami',89000.00,'https://covers.openlibrary.org/b/isbn/9780375704024-L.jpg','ebooks/ofrYiv6TLPGejNDVosH6tKcafRMERmWcNBG2Hbf4.pdf','Fiksi','published','2026-05-16 14:53:55','2026-05-20 14:36:11'),(19,'Pulang','pulang','Kisah keluarga, perjalanan, dan pulang pada makna hidup.','Tere Liye',49000.00,'https://covers.openlibrary.org/b/isbn/9786020822129-L.jpg','ebooks/AKASZx2Wmoc7k1smgcRpZYs2EDTIQL2rC31CubAn.pdf','Seri Novel','published','2026-05-16 14:53:55','2026-05-20 14:36:55'),(21,'Rich Dad Poor Dad','rich-dad-poor-dad','Pelajaran dasar tentang aset, uang, dan cara berpikir finansial.','Robert T. Kiyosaki',79000.00,'https://covers.openlibrary.org/b/isbn/9781612680194-L.jpg','ebooks/BiAz6TwK6f9lM9SMlyPiHQijAppyTnsMrFHymoTr.pdf','Ekonomi','published','2026-05-16 14:53:55','2026-05-20 14:38:20'),(22,'Thinking, Fast and Slow','thinking-fast-and-slow','Cara kerja pikiran manusia dalam mengambil keputusan.','Daniel Kahneman',110000.00,'https://covers.openlibrary.org/b/isbn/9780374533557-L.jpg','ebooks/TqFzniS9r74dyA3YPQwqAdRz0lTf8lV6tglOx33q.pdf','Pendidikan','published','2026-05-16 14:53:55','2026-05-20 14:38:50'),(23,'Deep Work','deep-work','Panduan fokus mendalam di tengah distraksi digital.','Cal Newport',85000.00,'https://covers.openlibrary.org/b/isbn/9781455586691-L.jpg','ebooks/gyptoQ9cGTnRypZyP4k7cJrLlUmk8pjibHXJ4qd2.pdf','Motivasi','published','2026-05-16 14:53:55','2026-05-20 14:39:20'),(24,'Start With Why','start-with-why','Mengapa tujuan yang jelas membuat organisasi lebih kuat.','Simon Sinek',88000.00,'https://covers.openlibrary.org/b/isbn/9781591846444-L.jpg','ebooks/vwJWs4cGvCnCvD6pE1fJxo386Mlk2zrDfSGT42RW.pdf','Motivasi','published','2026-05-16 14:53:55','2026-05-20 14:43:40'),(25,'Zero to One','zero-to-one','Cara membangun perusahaan dan produk yang benar-benar baru.','Peter Thiel',82000.00,'https://covers.openlibrary.org/b/isbn/9780804139298-L.jpg','ebooks/azzQcMmv2BBcDaB1Ab2KF7GLPau4KIuwrdVGhyft.pdf','Bisnis','published','2026-05-16 14:53:55','2026-05-20 14:41:04'),(26,'Good to Great','good-to-great','Riset tentang perusahaan yang berubah dari baik menjadi hebat.','Jim Collins',98000.00,'https://covers.openlibrary.org/b/isbn/9780066620992-L.jpg','ebooks/GqsSuUQeJ3Dm54jbrBt004klllIRcwZOMEZXELXV.pdf','Bisnis','published','2026-05-16 14:53:55','2026-05-20 14:42:32'),(27,'The Lean Startup','the-lean-startup','Metode membangun bisnis dengan eksperimen cepat.','Eric Ries',92000.00,'https://covers.openlibrary.org/b/isbn/9780307887894-L.jpg','ebooks/4F2pMR30KxJSPp8EauXi83eWIVoZlxDziWRCPrM1.pdf','Bisnis','published','2026-05-16 14:53:55','2026-05-20 14:44:29'),(28,'Economics in One Lesson','economics-in-one-lesson','Pengantar ekonomi klasik yang ringkas dan tajam.','Henry Hazlitt',75000.00,'https://covers.openlibrary.org/b/isbn/9780517548233-L.jpg','ebooks/hOZMo5fvTQ8oEKTC6daem1Id9SU67OyI4p6iZNkf.pdf','Ekonomi','published','2026-05-16 14:53:55','2026-05-20 14:45:09'),(29,'Freakonomics','freakonomics','Melihat ekonomi dari sudut pandang yang tidak biasa.','Steven D. Levitt',86000.00,'https://covers.openlibrary.org/b/isbn/9780060731335-L.jpg','ebooks/rX6vpztB4Kzs6ib8Ho6Wpnp2oP7T8k9dsoA9JaSV.pdf','Ekonomi','published','2026-05-16 14:53:55','2026-05-20 14:45:52'),(30,'Capital in the Twenty-First Century','capital-in-the-twenty-first-century','Kajian ketimpangan dan kapital dalam ekonomi modern.','Thomas Piketty',145000.00,'https://covers.openlibrary.org/b/isbn/9780674430006-L.jpg','ebooks/K6jtLz7OdPuOD8kbYFDTVHqPfVTkaTJLBDADfe3g.pdf','Ekonomi','published','2026-05-16 14:53:55','2026-05-20 14:49:10'),(31,'Clean Architecture','clean-architecture','Prinsip arsitektur perangkat lunak yang tahan perubahan.','Robert C. Martin',125000.00,'https://covers.openlibrary.org/b/isbn/9780134494166-L.jpg','ebooks/MIvbD3N0Y3EZJ4jZiJvHDywn7b3VEykF2hDlLmBQ.pdf','Teknologi','published','2026-05-16 14:53:55','2026-05-20 14:54:53'),(32,'JavaScript: The Good Parts','javascript-the-good-parts-1','Bagian terbaik JavaScript untuk menulis kode yang lebih baik.','Douglas Crockford',99000.00,'https://covers.openlibrary.org/b/isbn/9780596517748-L.jpg','ebooks/DAMfox0gOVcu4J4nkjnR2KQFAeljZJZKn0cekDIl.pdf','Teknologi','published','2026-05-16 14:53:55','2026-05-20 14:47:53'),(33,'Breath','breath','Sains dan praktik bernapas untuk kesehatan.','James Nestor',88000.00,'https://covers.openlibrary.org/b/isbn/9780735213616-L.jpg','ebooks/6JxFra8CQYRg6tt9bUb10kCZwbMUaMiKFChnXMlA.pdf','Kesehatan','published','2026-05-16 14:53:55','2026-05-20 14:49:49'),(34,'Why We Sleep','why-we-sleep','Mengapa tidur penting untuk tubuh dan pikiran.','Matthew Walker',96000.00,'https://covers.openlibrary.org/b/isbn/9781501144318-L.jpg','ebooks/vLXKyPR2DwQPZmuRN0Kwy2ehCWwTnl2vesEMq5FH.pdf','Kesehatan','published','2026-05-16 14:53:55','2026-05-20 14:50:53'),(35,'The Body Keeps the Score','the-body-keeps-the-score','Hubungan trauma, tubuh, dan proses pemulihan.','Bessel van der Kolk',105000.00,'https://covers.openlibrary.org/b/isbn/9780143127741-L.jpg','ebooks/RoMBGadHelmBSjIOpJjbdw42pahdWNpm6vCleaY9.pdf','Kesehatan','published','2026-05-16 14:53:55','2026-05-20 14:51:28'),(36,'Outlive','outlive','Strategi hidup panjang dan sehat berbasis sains.','Peter Attia',132000.00,'https://covers.openlibrary.org/b/isbn/9780593236598-L.jpg','ebooks/KaYsdAe5YfUiOCcRCbybqUTI15JKwM3w8dPZCNJn.pdf','Kesehatan','published','2026-05-16 14:53:55','2026-05-20 14:52:01'),(45,'HUJAN','hujan','NOVEL ROMANCE BEST SELLER','TERE LIYE',150000.00,'covers/Iz92CQfDVD1y6UI14EpVv4qe61T5gN5zuKYhMOCe.jpg','ebooks/9B81GMi91zszS0PkjuYeTHCJsYvQ94fxilt41qqX.pdf','Novel','published','2026-05-19 16:32:07','2026-05-19 16:32:53');
